export const COOKIE_NAME = 'mioon_session';

export function trustedOrigin(value) {
  const url = new URL(value);
  if (url.protocol !== 'http:' || url.hostname !== '127.0.0.1' || !url.port ||
      url.username || url.password || url.pathname !== '/' || url.search || url.hash) {
    throw new Error('Backend must use an ephemeral IPv4 loopback origin');
  }
  const port = Number(url.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('Invalid backend port');
  return url.origin;
}

export function isSameOrigin(value, origin) {
  try { const url = new URL(value); return url.origin === origin && !url.username && !url.password; }
  catch { return false; }
}

export function isAllowedNavigation(value, origin) {
  if (!isSameOrigin(value, origin)) return false;
  const url = new URL(value);
  const keys = [...url.searchParams.keys()];
  return url.pathname === '/' && !url.hash && (keys.length === 0 ||
    (keys.length === 1 && keys[0] === 'project' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(url.searchParams.get('project'))));
}

export function isAllowedRequest(value, origin) {
  if (isSameOrigin(value, origin)) return true;
  // Blob URLs are origin-bound and used only for in-memory media previews.
  try { const url = new URL(value); return url.protocol === 'blob:' && url.origin === origin; }
  catch { return false; }
}

export function isAllowedDownload(value, origin) {
  if (!isSameOrigin(value, origin)) return false;
  const url = new URL(value);
  return /^\/media\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(url.pathname) &&
    [...url.searchParams.keys()].every(key => key === 'download') && !url.hash;
}

export function secureWebPreferences(session) {
  return {
    session,
    contextIsolation: true,
    sandbox: true,
    nodeIntegration: false,
    nodeIntegrationInWorker: false,
    nodeIntegrationInSubFrames: false,
    webSecurity: true,
    allowRunningInsecureContent: false,
    experimentalFeatures: false,
    webviewTag: false,
    navigateOnDragDrop: false,
    spellcheck: false,
    devTools: false
    // No preload and no renderer IPC bridge: the shared UI uses only same-origin HTTP.
  };
}

export function sessionCookie(origin, token) {
  trustedOrigin(origin);
  if (typeof token !== 'string' || !/^[a-f0-9]{64}$/.test(token)) throw new Error('Invalid session token');
  return { url: origin, name: COOKIE_NAME, value: token, path: '/', secure: true,
    httpOnly: true, sameSite: 'strict' };
}

export function installSessionPolicy(session, origin, getWindow, { downloadsPath }) {
  session.setPermissionRequestHandler((_contents, _permission, callback) => callback(false));
  session.setPermissionCheckHandler(() => false);
  session.setDevicePermissionHandler(() => false);
  session.setDisplayMediaRequestHandler((_request, callback) => callback({}));
  session.on('will-download', (event, item, webContents) => {
    const win = getWindow();
    if (!win || win.isDestroyed() || webContents !== win.webContents ||
        !isAllowedNavigation(webContents.getURL(), origin) ||
        !item.getURLChain().every(url => isAllowedDownload(url, origin)) ||
        !isAllowedDownload(item.getURL(), origin) || item.getMimeType() !== 'video/mp4') {
      event.preventDefault();
      return;
    }
    // No automatic path writes: Chromium shows its native Save As / overwrite dialog.
    item.setSaveDialogOptions({ title: '保存视频', defaultPath: downloadsPath,
      filters: [{ name: 'MP4 视频', extensions: ['mp4'] }], properties: ['showOverwriteConfirmation'] });
  });
  session.webRequest.onBeforeRequest((details, callback) => callback({ cancel: details.resourceType === 'subFrame' || !isAllowedRequest(details.url, origin) }));
}

export function installWindowPolicy(win, origin) {
  const contents = win.webContents;
  const blockNavigation = (event, target) => { if (!isAllowedNavigation(event.url || target, origin)) event.preventDefault(); };
  contents.on('will-navigate', blockNavigation);
  contents.on('will-redirect', blockNavigation);
  contents.on('will-frame-navigate', event => {
    // Subframes are never needed, including same-origin frames.
    if (!event.isMainFrame || !isAllowedNavigation(event.url, origin)) event.preventDefault();
  });
  contents.on('will-attach-webview', event => event.preventDefault());
  contents.setWindowOpenHandler(() => ({ action: 'deny' }));
}

// A bounded stop may finish without an exit event. Keep the already-requested
// native quit pending in that case; never retry signals, restart the utility or
// close settings while the original owned utility could still be draining.
function confirmOwnedExit(backend, child) {
  return new Promise(resolve => {
    const confirmed = () => {
      if (backend.child === child) return;
      child.removeListener('exit', confirmed);
      resolve();
    };
    child.on('exit', confirmed);
    // The exit could have arrived between the rejected stop and this listener.
    confirmed();
  });
}

export async function stopBackendForQuit({ backend, cleanup, onUnconfirmed = () => {} }) {
  const child = backend?.child;
  let failure;
  try { await backend?.stop(); }
  catch (error) {
    if (error?.code === 'BACKEND_STOP_UNCONFIRMED' && child) {
      const confirmation = confirmOwnedExit(backend, child);
      // Notification failure cannot discard the owned child or trigger a quit
      // retry. Install the exact-child observer before showing a native dialog.
      try { void Promise.resolve(onUnconfirmed()).catch(() => {}); } catch {}
      await confirmation;
      if (backend.hasUnconfirmedMedia) throw Object.assign(new Error('本地服务已退出，但媒体子进程是否退出尚无法确认。'), {
        code: 'BACKEND_MEDIA_EXIT_UNCONFIRMED', exitConfirmed: true, mediaExitConfirmed: false
      });
      if (backend.shutdownFailed || (!backend.stopOutcome?.forced && backend.stopOutcome?.code !== 0)) {
        failure = Object.assign(new Error('本地服务退出时未能完成正常清理。'), {
          code: 'BACKEND_STOP_FAILED', exitConfirmed: true
        });
      }
    } else if (error?.exitConfirmed && error?.mediaExitConfirmed !== false && !backend?.child) failure = error;
    else throw error;
  }
  await cleanup();
  if (failure) throw failure;
}

import { EventEmitter } from 'node:events';
import { trustedOrigin } from './security.mjs';
import { createAgentSettingsBroker } from './secret-broker.mjs';
import { createImageSecretBroker } from './image-secret-broker.mjs';

// Normal worker drains finish inside the first phase. A signal being accepted
// is not proof of exit: keep the owned handle until Electron reports its exit.
export const BACKEND_STOP_BUDGET = Object.freeze({ gracefulMs: 10000, terminateMs: 2000, confirmMs: 1000 });
const stopError = (code, exitConfirmed) => Object.assign(new Error(code === 'BACKEND_STOP_UNCONFIRMED'
  ? '本地服务未确认退出。请稍后重试；在确认退出前不能重启服务。'
  : code === 'BACKEND_MEDIA_EXIT_UNCONFIRMED' ? '本地服务已退出，但媒体子进程是否退出尚无法确认。不能自动重启服务。'
  : '本地服务退出时未能完成正常清理。已保存的数据将在下次启动时恢复。'), { code, exitConfirmed });
const unconfirmedMediaError = () => Object.assign(stopError('BACKEND_MEDIA_EXIT_UNCONFIRMED', true), { mediaExitConfirmed: false });
const forceOwnedUtility = child => {
  const pid = child.pid;
  if (Number.isSafeInteger(pid) && pid > 1 && pid !== process.pid) process.kill(pid, 'SIGKILL');
};

export class BackendSupervisor extends EventEmitter {
  constructor({ fork, modulePath, environment, startupTimeout = 20000, stopTimeout = BACKEND_STOP_BUDGET.gracefulMs,
    terminateTimeout = BACKEND_STOP_BUDGET.terminateMs, exitTimeout = BACKEND_STOP_BUDGET.confirmMs,
    forceKill = forceOwnedUtility, agentSettings, imageSecretCodec }) {
    super();
    for (const value of [startupTimeout, stopTimeout, terminateTimeout, exitTimeout]) {
      if (!Number.isSafeInteger(value) || value < 0 || value > 60000) throw new Error('Invalid backend lifecycle budget');
    }
    Object.assign(this, { fork, modulePath, environment, startupTimeout, stopTimeout, terminateTimeout, exitTimeout,
      forceKill, agentSettings, imageSecretCodec });
    this.state = 'idle';
    this.mediaPids = new Set();
    this.mediaKinds = new Map();
    this.hasUnconfirmedMedia = false;
  }

  start(config) {
    if (this.hasUnconfirmedMedia) throw unconfirmedMediaError();
    if (this.child || this.stopping || !['idle', 'stopped', 'failed'].includes(this.state)) throw new Error('Backend already active');
    this.state = 'starting';
    this.origin = null;
    this.expectedExit = false;
    this.stopFailure = null;
    this.stopOutcome = null;
    this.shutdownFailed = false;
    this.stopForced = false;
    return new Promise((resolve, reject) => {
      let settled = false;
      let timer;
      let heartbeat;
      const fail = error => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        this.cancelStart = null;
        this.state = 'failed';
        reject(error);
      };
      this.cancelStart = () => fail(Object.assign(new Error('本地服务启动已取消'), { code: 'BACKEND_START_CANCELLED' }));
      let child;
